create table if not exists public.outcome_review_queue (id uuid primary key default gen_random_uuid(),source_type text not null,source_id uuid not null,enterprise_id uuid references public.enterprises(id) on delete cascade,proposed_story boolean not null default false,proposed_esg_asset boolean not null default false,status public.review_status not null default 'submitted',review_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_type,source_id)); alter table public.outcome_review_queue enable row level security; create policy "outcome queue admin read" on public.outcome_review_queue for select to authenticated using (private.is_admin(null)); create index if not exists idx_outcome_review_queue_status_created on public.outcome_review_queue(status,created_at desc); create or replace function public.queue_completed_outcome(p_source_type text,p_source_id uuid,p_enterprise_id uuid default null,p_story boolean default true,p_esg boolean default false) returns uuid language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_id uuid; begin if v_actor is null or not exists(select 1 from public.admin_roles ar where ar.user_id=v_actor and ar.role_key in ('super_admin','admin','network_manager','activity_reviewer','enterprise_reviewer')) then raise exception 'insufficient_privilege'; end if; insert into public.outcome_review_queue(source_type,source_id,enterprise_id,proposed_story,proposed_esg_asset,status) values(p_source_type,p_source_id,p_enterprise_id,p_story,p_esg,'submitted') on conflict(source_type,source_id) do update set enterprise_id=coalesce(excluded.enterprise_id,outcome_review_queue.enterprise_id),proposed_story=outcome_review_queue.proposed_story or excluded.proposed_story,proposed_esg_asset=outcome_review_queue.proposed_esg_asset or excluded.proposed_esg_asset,updated_at=now() returning id into v_id; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'outcome_reviewer','queue_outcome','outcome_review_queue',v_id::text,p_source_type); return v_id; end; $$; revoke all on function public.queue_completed_outcome(text,uuid,uuid,boolean,boolean) from public,anon; grant execute on function public.queue_completed_outcome(text,uuid,uuid,boolean,boolean) to authenticated;
